package com.enterpriseflow.entity; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="meetings") public class Meeting {@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;private String title;@ManyToOne(fetch=FetchType.LAZY)private Project project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(nullable=false)private User organizer;private Instant scheduledAt;@Column(columnDefinition="TEXT")private String transcript;@Column(columnDefinition="TEXT")private String summary;@Column(columnDefinition="TEXT")private String decisions;private String timezone;@Column(name="external_link",length=1000)private String externalLink;@ManyToMany @JoinTable(name="meeting_invitees",joinColumns=@JoinColumn(name="meeting_id"),inverseJoinColumns=@JoinColumn(name="user_id"))private Set<User> invitees=new HashSet<>();private Instant createdAt;protected Meeting(){}public Meeting(String t,Project p,User o,Instant at,String tr,String timezone,String externalLink,Collection<User> invitees){title=t;project=p;organizer=o;scheduledAt=at;transcript=tr;this.timezone=timezone;this.externalLink=externalLink;if(invitees!=null)this.invitees.addAll(invitees);} @PrePersist void on(){createdAt=Instant.now();}public UUID getId(){return id;}public String getTitle(){return title;}public Project getProject(){return project;}public User getOrganizer(){return organizer;}public Instant getScheduledAt(){return scheduledAt;}public String getTranscript(){return transcript;}public String getSummary(){return summary;}public String getDecisions(){return decisions;}public String getTimezone(){return timezone;}public String getExternalLink(){return externalLink;}public Set<User> getInvitees(){return invitees;}public void analyze(){if(transcript==null||transcript.isBlank())throw new IllegalArgumentException("A transcript is required before creating a summary.");String[] sentences=transcript.trim().split("(?<=[.!?])\\s+");summary=String.join(" ",java.util.Arrays.stream(sentences).limit(3).toList());decisions=java.util.Arrays.stream(sentences).filter(s->s.toLowerCase().matches(".*\\b(decided|approve|agreed|will)\\b.*")).limit(5).reduce("",(a,b)->a+(a.isBlank()?"":"\n")+b);}}
